      k_87ab1fc6e15f: "لا يتطلب مصادقة (لا يحتاج X-API-Key)\n\nResponse:\n{\n  \"status\": \"ok\",\n  \"timestamp\": \"2024-01-05T10:30:00Z\",\n  \"version\": \"v1\"\n}\n\nاستخدم هذا endpoint للتحقق من أن API يعمل\nوأن رابط الخادم صحيح قبل تنفيذ طلبات أخرى.",
