      k_33056e4072e0: "Headers:\nX-API-Key: YOUR_API_KEY\nContent-Type: application/json\n\nBody:\n{\n  \"recipient\": \"218912345678\",\n  \"type\": \"template\",\n  \"template_name\": \"otp\",\n  \"template_language\": \"ar\",\n  \"template_params\": [\"123456\"]\n}\n\nResponse:\n{\n  \"success\": true,\n  \"message_id\": \"wamid.xxx\",\n  \"recipient\": \"218912345678\"\n}\n\nNotes:\n- template_name: the approved WhatsApp template name\n- template_language: language code (ar, en, ...)\n- template_params: a simple array for body fields only, replacing {{1}}, {{2}}, ...\n- If the template has a header or dynamic URL buttons, use template_components as shown in the next example.\n- You can also use the short form: {\"template\": \"otp\", \"params\": [\"123456\"]}\n- The template must be in approved status to work.",
