      k_ebd0fcdd7b43: "Headers:\nX-API-Key: YOUR_API_KEY\nContent-Type: application/json\n\n// Example 1: button message\nBody:\n{\n  \"recipient\": \"218912345678\",\n  \"interactive_type\": \"button\",\n  \"body_text\": \"Choose one option:\",\n  \"header_text\": \"Main menu\",\n  \"footer_text\": \"Savana Platform\",\n  \"buttons\": [\n    { \"id\": \"btn_1\", \"title\": \"Technical support\" },\n    { \"id\": \"btn_2\", \"title\": \"Sales\" },\n    { \"id\": \"btn_3\", \"title\": \"Inquiries\" }\n  ]\n}\n\n// Example 2: list message\nBody:\n{\n  \"recipient\": \"218912345678\",\n  \"interactive_type\": \"list\",\n  \"body_text\": \"Choose from the list:\",\n  \"list_button_text\": \"Show options\",\n  \"sections\": [\n    {\n      \"title\": \"Services\",\n      \"rows\": [\n        { \"id\": \"svc_1\", \"title\": \"Service 1\", \"description\": \"Short description\" },\n        { \"id\": \"svc_2\", \"title\": \"Service 2\", \"description\": \"Short description\" }\n      ]\n    }\n  ]\n}\n\nResponse:\n{\n  \"success\": true,\n  \"message_id\": \"wamid.xxx\",\n  \"recipient\": \"218912345678\"\n}\n\nNotes:\n- interactive_type: \"button\" or \"list\"\n- Buttons: 1-3 buttons maximum, title up to 20 characters\n- List: up to 10 items across all sections",
